import heapq

def dijkstra(graph: dict, start: int) -> dict:
    # Initialize distances to infinity, except for the start section
    distances = {section: float('inf') for section in graph}
    distances[start] = 0

    # Priority queue to store sections and their distances
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_section = heapq.heappop(priority_queue)

        # If the current distance is greater than the recorded distance, skip it
        if current_distance > distances[current_section]:
            continue

        # Explore neighbors
        for neighbor, weight in graph[current_section].items():
            tentative_distance = current_distance + weight

            # If a shorter path is found, update the distance and add to the priority queue
            if tentative_distance < distances[neighbor]:
                distances[neighbor] = tentative_distance
                heapq.heappush(priority_queue, (tentative_distance, neighbor))

    return distances

# Example usage
graph = {
    0: {1: 4, 2: 1},
    1: {3: 1},
    2: {1: 2, 3: 5},
    3: {}
}

