def max_binary(s: str, k: int) -> str:
    # Count the number of '0's in the string
    num_zeros = s.count('0')

    # If k is greater than or equal to the number of '0's, flip all '0's to '1'
    if k >= num_zeros:
        return '1' * len(s)

    # Otherwise, flip the first k '0's to '1'
    result = list(s)
    for i in range(k):
        result[i] = '1'

    return ''.join(result)

