def bubble_sort_descending(arr, n):
    # Base case: if the array has only one element or is empty, it's already sorted
    if n <= 1:
        return arr

    # Perform a single pass of bubble sort
    for i in range(n - 1):
        # If the current element is less than the next element, swap them
        if arr[i] < arr[i + 1]:
