def unique_number(stream: List[Tuple[int, str]]) -> Optional[int]:
    # Initialize a bitmask with a size of 10^6 + 1 (since numbers are non-negative)
    bitmask = [0] * (10**6 + 1)

    # Iterate through each transaction in the stream
    for number, sign in stream:
        # Update the bitmask based on the sign
        if sign == '+':
            bitmask[number] ^= 1
        else:
            bitmask[number] ^= 1

    # Find the unique number
    unique_number = None
    for i, bit in enumerate(bitmask):
        if bit == 1:
            if unique_number is not None:
                return None  # More than one unique number
            unique_number = i

    return unique_number

