def most_frequent_product(transactions: list) -> str:
    # Initialize an empty dictionary to store the count of each product
    product_count = {}

    # Iterate over each transaction in the list
    for transaction in transactions:
        # If the product is already in the dictionary, increment its count
        if transaction in product_count:
            product_count[transaction] += 1
        # Otherwise, add the product to the dictionary with a count of 1
        else:
            product_count[transaction] = 1

    # Initialize variables to track the most frequent product and its count
    most_frequent = None
    max_count = 0

    # Iterate over the dictionary to find the product with the maximum count
    for product, count in product_count.items():
        # If this product has a higher count than the current maximum, update the most frequent product
        if count > max_count:
            most_frequent = product
            max_count = count

    # Return the most frequent product
